        q.push(root);
        int level = 1;
        long long min_sum = LLONG_MAX;
        int ans_level = 1;
        while (!q.empty()) {
            int sz = q.size();
            long long cur_sum = 0;
            for (int i = 0; i < sz; ++i) {
                TreeNode* node = q.front();
                q.pop();
                cur_sum += node->val;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
